-- Source rows for facilities.FactFacilityOwnership: the logic of the table.
-- Generated by `python -m fde render` from models/gold/facilities/FactFacilityOwnership.sql. Do not edit: change the spec and render again.

IF SCHEMA_ID('stage') IS NULL
    EXEC('CREATE SCHEMA [stage]');
GO

CREATE OR ALTER VIEW [stage].[FactFacilityOwnershipSource]
AS
with

ownership as (

    select * from [lh_silver].[dbo].[facilityownership]

),

facility as (

    select * from [facilities].[DimFacility]

),

data_source as (

    select * from [facilities].[DimDataSource]

)

select
    ownership.FacilityOwnership_BK,
    coalesce(facility.DimFacility_SK, -1) as DimFacility_SK,
    coalesce(data_source.DimDataSource_SK, -1) as DimDataSource_SK,
    ownership.OwnershipYear,
    ownership.Owners,
    ownership.Operators
from ownership
left join facility
    on facility.Facility_BK = ownership.Facility_BK
left join data_source
    on data_source.DataSource_BK = ownership.DataSource_BK
GO
